begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('42000000-0000-4000-8000-000000000001','phase3-audit@example.test');
select set_config('request.jwt.claim.sub','42000000-0000-4000-8000-000000000001',true);
select public.complete_onboarding('phase3_audit','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','B1','UTC');
create temporary table saved as select public.get_or_create_today_challenge() payload;
insert into public.vocabulary_concepts(id,concept_key,category,is_photographable) values('42000000-0000-4000-8000-000000000002','AUDIT_UNUSED_MEANING','test',true);
insert into public.languages(id,code,name,native_name) values('42000000-0000-4000-8000-000000000003','zz','Audit language','Audit language');
select throws_ok($$update public.vocabulary_terms set concept_id='42000000-0000-4000-8000-000000000002' where id=(select (payload->'words'->0->>'vocabulary_term_id')::uuid from saved)$$,'23503',null,'Used target term cannot move to another meaning');
select throws_ok($$update public.vocabulary_terms set concept_id='42000000-0000-4000-8000-000000000002' where id=(select (payload->'words'->0->>'reference_term_id')::uuid from saved)$$,'23503',null,'Used reference term cannot move to another meaning');
select throws_ok($$update public.vocabulary_terms set language_id='42000000-0000-4000-8000-000000000003' where id=(select (payload->'words'->0->>'vocabulary_term_id')::uuid from saved)$$,'23503',null,'Used target term cannot move to another language');
select throws_ok($$update public.vocabulary_terms set language_id='42000000-0000-4000-8000-000000000003' where id=(select (payload->'words'->0->>'reference_term_id')::uuid from saved)$$,'23503',null,'Used reference term cannot move to another language');
select lives_ok($$update public.vocabulary_terms set term=term||' corrected',cefr_level='C2',is_active=false where id in ((select (payload->'words'->0->>'vocabulary_term_id')::uuid from saved),(select (payload->'words'->0->>'reference_term_id')::uuid from saved))$$,'Text/CEFR/activation edits remain possible for used terms');
select is(public.get_or_create_today_challenge(),(select payload from saved),'Saved cards retain text, level and linked identities after catalog edits');
select lives_ok($$update public.vocabulary_terms set concept_id='42000000-0000-4000-8000-000000000002',language_id='42000000-0000-4000-8000-000000000003' where id=(select t.id from public.vocabulary_terms t where not exists(select 1 from public.daily_challenge_words w where w.vocabulary_term_id=t.id or w.reference_term_id=t.id) limit 1)$$,'An unused catalog row can still have its meaning/language corrected');

select public.replace_daily_challenge_word((select (payload->'words'->1->>'id')::uuid from saved)) is not null;
select throws_ok($$delete from public.daily_challenge_words where id=(select (payload->'words'->1->>'id')::uuid from saved)$$,'23514','assignment_history_immutable','Retired history cannot be removed from a retained challenge');
select throws_ok($$delete from public.daily_challenge_words where id=(select (payload->'words'->2->>'id')::uuid from saved)$$,'23514','assignment_history_immutable','Active assignment cannot be deleted and rewritten');
select is((select count(*) from public.daily_challenge_words where daily_challenge_id=(select (payload->'challenge'->>'id')::uuid from saved))::integer,4,'Both failed deletes retain full history');
select throws_ok($$update public.daily_challenge_words set target_language_id='42000000-0000-4000-8000-000000000003' where id=(select (payload->'words'->0->>'id')::uuid from saved)$$,'23514','assignment_history_immutable','Language snapshots are immutable alongside word history');
select throws_ok($$select private.slot_level('invalid','target')$$,'23514','invalid_cefr_slot','Invalid CEFR never falls back to C2');
select throws_ok($$select private.slot_level('B1','invalid')$$,'23514','invalid_cefr_slot','Invalid slot never falls back to C2');
select throws_ok($$select private.slot_level(null,'review')$$,'23514','invalid_cefr_slot','Missing CEFR fails closed');
select throws_ok($$select private.slot_level('C2',null)$$,'23514','invalid_cefr_slot','Missing slot fails closed');
select is(private.slot_level('A1','review'),'A1','Valid A1 boundary remains clamped');
select is(private.slot_level('C2','stretch'),'C2','Valid C2 boundary remains clamped');
select ok(not has_function_privilege('authenticated','private.preserve_assignment_history()','execute'),'New elevated history helper is not client-callable');
set constraints all immediate;
select lives_ok($$delete from auth.users where id='42000000-0000-4000-8000-000000000001'$$,'Account erasure still cascades through all assignment history');
select is((select count(*) from public.daily_challenge_words where daily_challenge_id=(select (payload->'challenge'->>'id')::uuid from saved))::integer,0,'Cascade leaves no orphan assignment rows');
select * from finish();
rollback;
